local function AppendEntries(dst, src)
    for _, entry in ipairs(src or {}) do
        table.insert(dst, entry)
    end
end

local function BuildLevelBuckets(entries)
    local buckets = {
        L1_3 = {},
        L4_5 = {},
        L6_9 = {},
    }

    for _, entry in ipairs(entries or {}) do
        local level = tonumber(entry and entry.level) or 1
        if level <= 3 then
            table.insert(buckets.L1_3, entry)
        elseif level <= 5 then
            table.insert(buckets.L4_5, entry)
        else
            table.insert(buckets.L6_9, entry)
        end
    end

    return buckets
end

-- Canonical merged list consumed by provider registration/runtime.
Summons.List = {}
AppendEntries(Summons.List, Summons.Bands.COMMON)
AppendEntries(Summons.List, Summons.Bands.VETERAN)
AppendEntries(Summons.List, Summons.Bands.ELITE)
AppendEntries(Summons.List, Summons.Bands.LEGENDARY)
AppendEntries(Summons.List, Summons.Bands.CHAMPION_ONLY)

Summons.Buckets = BuildLevelBuckets(Summons.List)
Summons.L1_3 = Summons.Buckets.L1_3
Summons.L4_5 = Summons.Buckets.L4_5
Summons.L6_9 = Summons.Buckets.L6_9

return Summons


